{"name":"__intel_runtime_pm_get","qualified_name":"workspace-linux.drivers.gpu.drm.i915.intel_runtime_pm.__intel_runtime_pm_get","label":"Function","file_path":"/workspace/linux/drivers/gpu/drm/i915/intel_runtime_pm.c","start_line":166,"end_line":179,"source":"static intel_wakeref_t __intel_runtime_pm_get(struct intel_runtime_pm *rpm,
					      bool wakelock)
{
	struct drm_i915_private *i915 = rpm_to_i915(rpm);
	int ret;

	ret = pm_runtime_get_sync(rpm->kdev);
	drm_WARN_ONCE(&i915->drm, ret < 0,
		      "pm_runtime_get_sync() failed: %d\n", ret);

	intel_runtime_pm_acquire(rpm, wakelock);

	return track_intel_runtime_pm_wakeref(rpm);
}
